import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  listNotifications,
  notify,
  resolveChannels,
} from "@/server/services/notification-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("notify", "growth");
});

afterAll(() => {
  cleanup();
});

describe("services/notification-service", () => {
  // comment.created with mentions produces one comment_mention per mentioned user.
  it("creates one notification per mentioned user", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mentions-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});

/**
 * Webhook endpoints and their delivery attempts.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, webhookDeliveries, webhookEndpoints } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { CreateWebhookInput, UpdateWebhookInput } from "@/schemas/webhook";
import type {
  WebhookDeliveryRow,
  WebhookEndpointRow,
} from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, WebhookId } from "@/types/common";

export async function listEndpoints(
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  return getDb()
    .select()
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .orderBy(asc(webhookEndpoints.createdAt))
    .all();
}

export async function insertEndpoint(
  input: CreateWebhookInput,
  secret: string,
): Promise<WebhookEndpointRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookEndpoints)
    .values({
      id: newId(),
      orgId: input.orgId,
      url: input.url,
      secret,
      eventTypes: JSON.stringify(input.eventTypes),
      enabled: true,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

export async function updateEndpoint(
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  const row = getDb()
    .update(webhookEndpoints)
    .set({
      ...(input.url === undefined ? {} : { url: input.url }),
      ...(input.eventTypes === undefined
        ? {}
        : { eventTypes: JSON.stringify(input.eventTypes) }),
      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, input.orgId),
        eq(webhookEndpoints.id, input.webhookId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);
  return row;
}

export async function deleteEndpoint(
  orgId: OrgId,
  webhookId: WebhookId,
): Promise<void> {
  const db = getDb();
  db.delete(webhookDeliveries)
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.endpointId, webhookId),
      ),
    )
    .run();
  db.delete(webhookEndpoints)
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, orgId),
        eq(webhookEndpoints.id, webhookId),
      ),
    )
    .run();
}

/** The `webhooks` quota compares against this. */
export async function countEndpoints(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function enqueueDelivery(
  orgId: OrgId,
  endpointId: string,
  eventType: string,
  payload: string,
): Promise<WebhookDeliveryRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

/**
 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
 * drained by a background worker, not by a request — and the attempt counter
 * is bumped on claim so a crashed worker cannot retry forever.
 */
export async function claimPendingDeliveries(
  limit: number,
): Promise<readonly WebhookDeliveryRow[]> {
  const db = getDb();
  const pending = db
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.status, "pending"))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

export async function markDelivered(
  orgId: OrgId,
  deliveryId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({ status: "delivered", deliveredAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

export async function markDeliveryFailed(
  orgId: OrgId,
  deliveryId: string,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}
